    describe('SetFlowVariables - Transform (XML → Fluent)', () => {
        test('SetFlowVariables values are preserved after transform', async () => {
            const project = ctx.createProject()
            const fluentContent = loadTestFile('set-flow-variables-simple.now.ts', 'flow-logics/fluent')
            project.addFile({ path: 'set-flow-variables-simple.now.ts', content: fluentContent })
            const buildOutput = await project.getFile('set-flow-variables-simple.now.ts')!.getOutput()
            const flowXml = buildOutput.find((f) => f.path.includes('sys_hub_flow'))
            expect(flowXml).toBeDefined()

            // Transform XML back to Fluent
            const transformProject = ctx.createProject()
            const { changedFiles } = await transformProject.transform({
                path: flowXml!.path,
                content: flowXml!.content,
            })

            expect(changedFiles).toHaveLength(1)
            const transformedContent = changedFiles[0].getContent()

            // Verify setFlowVariables values are preserved in transformed output
            expect(transformedContent).toContain('wfa.flowLogic.setFlowVariables(')
            expect(transformedContent).toContain("annotation: 'Set basic flow variables'")
            expect(transformedContent).toContain("status: 'active'")
            expect(transformedContent).toContain("count: '42'")
            expect(transformedContent).toContain("isActive: 'true'")
        })
    })
